import{_ as a}from"./chunks/academic-cross-substrate-authority-layers.1crA5U68.js";import{_ as s,C as n,o as r,c as i,E as o,a2 as l}from"./chunks/framework.BOeh4kYD.js";const g=JSON.parse(`{"title":"An Agent Is Not an Authority Boundary: What Cross-Substrate Failures Reveal","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"An Agent Is Not an Authority Boundary: What Cross-Substrate Failures Reveal","date":"2026-09-16","column":"digital-employee","category":"academic","article_type":"technical-analysis","edition":"research-center","research_question":"When files, visible memory and ordinary workspace evidence look the same, what additional authority state must survive until a consequential agent action becomes an effect?","summary":"A new controlled study shows that identical planner-visible workspaces can require opposite safe publication decisions when actor-attempt authorization lives elsewhere. Its most important result is not that models reason perfectly once permissions are shown, but that execution-time authority checks can stop fixed unsafe intents without changing the model's plan.","sources":"arXiv:2609.08472; research/reading/A-20260916-01-cross-substrate-authority.md; research/analysis/A-20260916-01-cross-substrate-authority.md","cover":"/assets/covers/academic-cross-substrate-authority-boundary-cover-v2.webp"},"headers":[],"relativePath":"en/digital-employee/2026-09-16-cross-substrate-authority-boundary.md","filePath":"en/digital-employee/2026-09-16-cross-substrate-authority-boundary.md","lastUpdated":1789665186000}`),p={name:"en/digital-employee/2026-09-16-cross-substrate-authority-boundary.md"};function c(h,e,d,u,m,y){const t=n("ArticleCover");return r(),i("div",null,[o(t,{image:"/assets/covers/academic-cross-substrate-authority-boundary-cover-v2.webp",kicker:"Digital Employee · Academic Observation 008",title:"An Agent Is Not an Authority Boundary",summary:"The model may see the files. It may even see the permission. What decides whether the next mutation is actually authorized?",version:"DE008",status:"Academic Runtime V5 · 2026-09-16",languageHref:"/zh/digital-employee/2026-09-16-cross-substrate-authority-boundary",languageLabel:"中文"}),e[0]||(e[0]=l(`<h1 id="an-agent-is-not-an-authority-boundary-what-cross-substrate-failures-reveal" tabindex="-1">An Agent Is Not an Authority Boundary: What Cross-Substrate Failures Reveal <a class="header-anchor" href="#an-agent-is-not-an-authority-boundary-what-cross-substrate-failures-reveal" aria-label="Permalink to &quot;An Agent Is Not an Authority Boundary: What Cross-Substrate Failures Reveal&quot;">​</a></h1><p>Two agent runs can end with the same files.</p><p>They can expose the same Git diff, the same visible memory, and the same candidate artifact. One should be published. The other should be blocked.</p><p>If that sounds contradictory, the missing fact is not in the files at all.</p><p>The paper <strong>Beyond Agent Harnesses: Cross-Substrate Authority for Multi-Agent Systems</strong>, first posted to arXiv on September 8, 2026, studies exactly this case. Its central claim is that multi-agent systems can develop a <strong>cross-substrate authority gap</strong>: the planner sees workspace and memory state, while the authorization that determines whether a downstream effect is allowed lives in another runtime, registry, or approval service.</p><p>That distinction is easy to miss because modern agent systems are very good at making everything look like context. A policy can be pasted into a system prompt. An approval can be summarized into memory. A shared file can record who supposedly changed it. Yet none of those representations necessarily proves that <strong>this actor, in this execution attempt, is currently authorized to cause this effect on these bytes for this consumer scope</strong>.</p><p>The important boundary may therefore be somewhere other than the model session itself.</p><h2 id="same-bytes-opposite-correct-actions" tabindex="-1">Same bytes, opposite correct actions <a class="header-anchor" href="#same-bytes-opposite-correct-actions" aria-label="Permalink to &quot;Same bytes, opposite correct actions&quot;">​</a></h2><p>The paper&#39;s motivating construction is deliberately uncomfortable.</p><p>Imagine two coding agents modifying a shared policy file and its consumer. In both worlds, the downstream agent sees byte-identical final files, the same uncommitted Git evidence, and the same visible memory.</p><p>In the <strong>aligned</strong> world, each writer was authorized for its assigned scope. Publication is allowed.</p><p>In the <strong>crossed</strong> world, the writers were swapped across scopes. The final bytes happen to be the same, but the artifact must be held for reconciliation.</p><p>The planner-visible observation is identical while the correct action changes.</p><p>The authors formalize this as an observation-aliasing problem: if two worlds expose the same observation <code>O</code> but require opposite actions, a deterministic policy that only sees <code>O</code> must emit the same answer in both and therefore fail in at least one. Always blocking is safe but produces an unnecessary block in the authorized world.</p><p>This is not primarily a model-intelligence result. It is an <strong>information-boundary result</strong>.</p><p>If the fact that distinguishes two worlds is not present in the observation, better reasoning over that same observation cannot reconstruct the missing fact.</p><h2 id="authority-is-not-a-property-of-the-agent" tabindex="-1">Authority is not a property of “the agent” <a class="header-anchor" href="#authority-is-not-a-property-of-the-agent" aria-label="Permalink to &quot;Authority is not a property of “the agent”&quot;">​</a></h2><p>A common abstraction is to ask whether an agent is authorized.</p><p>That is often too coarse.</p><p>The paper instead represents a decision relation that binds several facts together: actor and attempt identity, session and consumer scope, input and artifact hashes, authorized action scope, terminal attempt state, downstream-use authorization, and an evidence generation.</p><p>The point is relational.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>not:</span></span>
<span class="line"><span>    agent_A = authorized</span></span>
<span class="line"><span></span></span>
<span class="line"><span>but closer to:</span></span>
<span class="line"><span>    actor A</span></span>
<span class="line"><span>    + attempt 17</span></span>
<span class="line"><span>    + artifact hash H</span></span>
<span class="line"><span>    + consumer scope S</span></span>
<span class="line"><span>    + action &quot;publish&quot;</span></span>
<span class="line"><span>    + terminal state</span></span>
<span class="line"><span>    + downstream authorization</span></span>
<span class="line"><span>    + evidence generation G</span></span>
<span class="line"><span>    = admissible relation</span></span></code></pre></div><p>The same agent may be authorized for one scope and not another. The same bytes may be publishable under one attempt lineage and blocked under another. A previously valid approval may become stale after the workspace changes or an authorization generation advances.</p><p>This is why “the agent had permission” is a weak audit statement unless permission is bound to the thing that actually happened.</p><h2 id="the-paper-separates-three-different-problems" tabindex="-1">The paper separates three different problems <a class="header-anchor" href="#the-paper-separates-three-different-problems" aria-label="Permalink to &quot;The paper separates three different problems&quot;">​</a></h2><p>One of the paper&#39;s strengths is that it does not treat “show the model the permission” and “enforce the permission” as the same mechanism.</p><p>Its three experiments form a useful progression.</p><h3 id="experiment-1-supply-the-missing-authority-fact" tabindex="-1">Experiment 1: supply the missing authority fact <a class="header-anchor" href="#experiment-1-supply-the-missing-authority-fact" aria-label="Permalink to &quot;Experiment 1: supply the missing authority fact&quot;">​</a></h3><p>The first experiment uses four held-out semantic templates, two model routes, two lineage directions, two external publication states, and four evidence arms, for 128 target executions across 32 matched strata.</p><p>The authors report:</p><ul><li>Git-only control <code>G0</code>: <strong>0/32</strong> final semantic success</li><li>candidate evidence without the authority fact <code>C0</code>: <strong>0/32</strong></li><li>canonical raw authority receipts <code>R0</code>: <strong>32/32</strong></li><li>the same admitted primitives packaged as a typed relation <code>W0</code>: <strong>32/32</strong></li></ul><p>These are source-reported results; this Academic run did not independently reproduce them.</p><p>The most useful interpretation is narrower than “typed governance solves the problem.” The <code>R0</code>–<code>C0</code> contrast shows that the missing external authority fact resolves the constructed ambiguity. The typed <code>W0</code> representation shows no observed final-semantic improvement over equal raw authority information in this experiment.</p><p>The information matters more than the packaging.</p><h3 id="experiment-2-planning-is-still-unreliable" tabindex="-1">Experiment 2: planning is still unreliable <a class="header-anchor" href="#experiment-2-planning-is-still-unreliable" aria-label="Permalink to &quot;Experiment 2: planning is still unreliable&quot;">​</a></h3><p>The second experiment asks whether planners can safely decide whether to publish an observation-equivalent shared worktree.</p><p>Across <strong>96 planning calls</strong>, the paper reports first-action correctness of <strong>14/32</strong> for ordinary workspace evidence, <strong>19/32</strong> with raw receipts, and <strong>15/32</strong> with the typed relation.</p><p>In crossed worlds, unsafe publication is reported at <strong>12/16</strong>, <strong>9/16</strong>, and <strong>6/16</strong> respectively.</p><p>But the last number is not a simple victory: the typed-relation arm also contains <strong>11/32 invalid or absent outputs</strong>. The model split is especially revealing. One route avoids unsafe publication partly because many rows do not produce a valid intent; another route parses the relation but still proposes unsafe publication in several crossed cases.</p><p>That is why a single “safety score” is misleading.</p><p>A planner can be conservative because it understands the rule, or because it fails to act. A system can block unsafe effects while also blocking too much. Decision quality, unsafe-effect rate, unnecessary block rate, and missing-intent rate are different measurements.</p><h3 id="experiment-3-keep-the-model-intent-fixed" tabindex="-1">Experiment 3: keep the model intent fixed <a class="header-anchor" href="#experiment-3-keep-the-model-intent-fixed" aria-label="Permalink to &quot;Experiment 3: keep the model intent fixed&quot;">​</a></h3><p>The third experiment is the most important for architecture.</p><p>The researchers take the exact <strong>32 first-action intents</strong> from the typed-relation arm in Experiment 2 and replay them with <strong>zero new model calls</strong>. The model does not get another chance to reason. Only the execution-time validator changes.</p><p>The paper reports that those fixed intents contain six unsafe crossed-world publication requests. With the execution guard in place, all six become safe non-effects. At the same time, all <strong>12/12 valid authorized publish intents</strong> are allowed, with <strong>0/12</strong> denials among that valid-intent set.</p><p>Within this fixed matrix, the effect changes without changing the model&#39;s intention.</p><p>That is the critical distinction.</p><h2 id="planner-evidence-and-effect-authority-are-different-layers" tabindex="-1">Planner evidence and effect authority are different layers <a class="header-anchor" href="#planner-evidence-and-effect-authority-are-different-layers" aria-label="Permalink to &quot;Planner evidence and effect authority are different layers&quot;">​</a></h2><p>A prompt can say:</p><blockquote><p>Publish only when the current actor is authorized for the artifact&#39;s scope.</p></blockquote><p>The model can read that rule. It can even repeat it perfectly.</p><p>But a prompt is still part of the planner&#39;s observation. It does not, by itself, make the effect boundary enforce the rule.</p><p>The paper&#39;s experiments motivate a two-part design:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>planning-time:</span></span>
<span class="line"><span>    expose authority evidence</span></span>
<span class="line"><span>    let the model reason and explain</span></span>
<span class="line"><span></span></span>
<span class="line"><span>execution-time:</span></span>
<span class="line"><span>    validate the actor / attempt / artifact / scope relation</span></span>
<span class="line"><span>    recheck policy-relevant bytes</span></span>
<span class="line"><span>    admit or deny the mutation</span></span></code></pre></div><p>The first layer improves informed judgment.</p><p>The second layer determines whether a proposed action becomes an effect.</p><p>This is not an argument against agent intelligence. It is an argument for giving intelligence a boundary it does not need to impersonate.</p><h2 id="research-center-synthesis-four-substrates-before-one-effect" tabindex="-1">Research Center synthesis: four substrates before one effect <a class="header-anchor" href="#research-center-synthesis-four-substrates-before-one-effect" aria-label="Permalink to &quot;Research Center synthesis: four substrates before one effect&quot;">​</a></h2><p>The following diagram is <strong>Research Center synthesis</strong>, not a figure reproduced from the paper and not an architecture standard claimed by its authors.</p><p><img src="`+a+`" alt="Conceptual synthesis of planner context, workspace bytes, durable attempt/provenance, authority state, and the mutation boundary."></p><p>A useful production model separates four substrates.</p><h3 id="_1-planner-visible-context" tabindex="-1">1. Planner-visible context <a class="header-anchor" href="#_1-planner-visible-context" aria-label="Permalink to &quot;1. Planner-visible context&quot;">​</a></h3><p>This is what the model can reason over: task instructions, memory, retrieved facts, policy text, tool results, and possibly authority receipts.</p><p>Its job is to support judgment.</p><h3 id="_2-workspace-and-artifact-bytes" tabindex="-1">2. Workspace and artifact bytes <a class="header-anchor" href="#_2-workspace-and-artifact-bytes" aria-label="Permalink to &quot;2. Workspace and artifact bytes&quot;">​</a></h3><p>This answers a different question: what material currently exists?</p><p>A content digest can prove which bytes were observed. It does not necessarily prove who was authorized to produce or publish them.</p><h3 id="_3-durable-attempt-and-provenance-state" tabindex="-1">3. Durable attempt and provenance state <a class="header-anchor" href="#_3-durable-attempt-and-provenance-state" aria-label="Permalink to &quot;3. Durable attempt and provenance state&quot;">​</a></h3><p>This binds work to an execution occurrence: which attempt ran, whether it reached a terminal state, what inputs it used, and which artifact it produced.</p><p>Without this layer, a shared workspace can erase the relation between material and the execution that produced it.</p><h3 id="_4-authority-state" tabindex="-1">4. Authority state <a class="header-anchor" href="#_4-authority-state" aria-label="Permalink to &quot;4. Authority state&quot;">​</a></h3><p>This answers whether the particular actor-attempt-artifact-scope relation is currently permitted to cross into a downstream effect.</p><p>The final mutation boundary should consume the relevant relation, not infer it from a conversational summary.</p><p>The resulting principle is simple:</p><blockquote><p><strong>Evidence may be visible to the model before an action, but authority must still survive until the action becomes real.</strong></p></blockquote><h2 id="git-can-be-enough-—-when-git-actually-carries-the-authority" tabindex="-1">Git can be enough — when Git actually carries the authority <a class="header-anchor" href="#git-can-be-enough-—-when-git-actually-carries-the-authority" aria-label="Permalink to &quot;Git can be enough — when Git actually carries the authority&quot;">​</a></h2><p>This paper should not be reduced to “Git is insufficient.”</p><p>The authors explicitly preserve an important negative control: authenticated commits can carry the needed authority relation when their metadata is authoritative for downstream use.</p><p>If a commit reliably binds actor, attempt, scope, artifact, and the relevant approval state, Git can be the authority boundary.</p><p>Cross-substrate governance becomes necessary when some required fact remains elsewhere: an approval service, a task runtime, a revocation registry, a mutable evidence generation, or an uncommitted shared workspace.</p><p>So the better question is not:</p><blockquote><p>Git or an Agentic OS?</p></blockquote><p>It is:</p><blockquote><p><strong>Where does the authoritative relation live, and can the downstream effect validate it without guessing?</strong></p></blockquote><p>That formulation is much more portable.</p><h2 id="completed-and-approved-for-downstream-use-are-not-synonyms" tabindex="-1">“Completed” and “approved for downstream use” are not synonyms <a class="header-anchor" href="#completed-and-approved-for-downstream-use-are-not-synonyms" aria-label="Permalink to &quot;“Completed” and “approved for downstream use” are not synonyms&quot;">​</a></h2><p>Another useful distinction in the paper&#39;s relation is the separation between an attempt&#39;s terminal state and downstream-use authorization.</p><p>An agent may successfully complete a task without its output being approved for publication.</p><p>A review can approve an artifact and later be invalidated by workspace drift.</p><p>A publishable artifact can remain identical while the actor attempting to publish it changes.</p><p>Collapsing these states into one boolean such as <code>done=true</code> creates exactly the kind of ambiguity the paper is designed to expose.</p><p>For durable agent work, at least these questions should remain independent:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Did the work finish?</span></span>
<span class="line"><span>Which attempt produced these bytes?</span></span>
<span class="line"><span>Are these still the same bytes?</span></span>
<span class="line"><span>Was downstream use approved?</span></span>
<span class="line"><span>For which actor and scope?</span></span>
<span class="line"><span>Is that approval still current?</span></span></code></pre></div><p>A lifecycle state answers only part of the story.</p><h2 id="the-paper-is-not-a-complete-security-model" tabindex="-1">The paper is not a complete security model <a class="header-anchor" href="#the-paper-is-not-a-complete-security-model" aria-label="Permalink to &quot;The paper is not a complete security model&quot;">​</a></h2><p>The evidence boundary matters.</p><p>The experiments are controlled mini-benchmarks over two four-template families and two model routes. Experiment 3 reuses 32 previously generated intents. The authors explicitly say that deployment prevalence requires a separate sampling design.</p><p>The study also assumes a nonmalicious host, authentic actor credentials, an uncompromised authority database, and collision-resistant hashes.</p><p>It does not solve:</p><ul><li>malicious-host compromise,</li><li>stolen actor credentials,</li><li>cryptographic identity at scale,</li><li>multi-tenant policy composition,</li><li>semantic business judgment,</li><li>every possible concurrency or recovery failure.</li></ul><p>The result is strongest when read as a mechanism study: <strong>when authority state is decision-critical and hidden outside the planner-visible substrate, exposing it helps resolve ambiguity, but reliable downstream effects still benefit from an independently validated execution boundary.</strong></p><p>That is already a substantial result. It does not need to become a universal security claim.</p><h2 id="safety-and-availability-should-be-reported-separately" tabindex="-1">Safety and availability should be reported separately <a class="header-anchor" href="#safety-and-availability-should-be-reported-separately" aria-label="Permalink to &quot;Safety and availability should be reported separately&quot;">​</a></h2><p>The planning experiment also offers a measurement lesson.</p><p>A system that denies every action can produce zero unsafe publications. That does not make it useful.</p><p>A model that emits no valid action in difficult cases may appear safer on one denominator while failing availability on another.</p><p>Production dashboards should therefore separate at least:</p><ul><li>unsafe effects,</li><li>valid authorized effects admitted,</li><li>unnecessary blocks,</li><li>invalid or missing intents,</li><li>stale-evidence denials,</li><li>recovery-required cases.</li></ul><p>This is a healthier pattern than one composite “agent safety” number.</p><p>It also helps locate responsibility. Planner quality and execution enforcement can improve independently.</p><h2 id="a-practical-rule-for-digital-work" tabindex="-1">A practical rule for digital work <a class="header-anchor" href="#a-practical-rule-for-digital-work" aria-label="Permalink to &quot;A practical rule for digital work&quot;">​</a></h2><p>The paper&#39;s practical lesson can be stated without adopting any particular operating-system metaphor:</p><p><strong>Do not make the agent session itself the proof that an effect is authorized.</strong></p><p>Let the model reason about evidence. Let it propose actions. Let it explain why a publication, database write, handoff, or external call appears justified.</p><p>But before a consequential mutation crosses the boundary, make the system answer a more exact question:</p><blockquote><p>Does the current, validated relation still authorize <strong>this actor, this attempt, this artifact, this action, for this consumer scope, under this evidence version</strong>?</p></blockquote><p>If the answer cannot be established, the system should preserve the uncertainty as a block or reconciliation state rather than manufacture authority from context.</p><p>That is different from distrusting the model.</p><p>It is recognizing that <strong>reasoning and authorization are different jobs</strong>.</p><h2 id="what-remains-open" tabindex="-1">What remains open <a class="header-anchor" href="#what-remains-open" aria-label="Permalink to &quot;What remains open&quot;">​</a></h2><p>The next research questions are not small.</p><p>How should authority relations work across organizations? How should revocation propagate when artifacts have already been handed off? When can a signed Git commit substitute for an external registry? Which predicates should be deterministic, and which require human or model judgment? How should a recovered runtime prove that a prior external effect did or did not occur? How should an authority store itself be audited or replicated?</p><p>Those questions extend beyond this paper&#39;s fixed experiments.</p><p>But the current work makes one design mistake harder to defend: treating a coherent model context as if it were also the final authority boundary.</p><p>The agent can know.</p><p>The workspace can match.</p><p>The plan can make sense.</p><p>And the effect can still be unauthorized.</p><h2 id="sources-and-evidence-boundary" tabindex="-1">Sources and evidence boundary <a class="header-anchor" href="#sources-and-evidence-boundary" aria-label="Permalink to &quot;Sources and evidence boundary&quot;">​</a></h2><ol><li>Yang Li, Sergey Volkov, Hai Liu, Zongsi Xu, Xiyu Chen, Tuo Zhou, Dian Shao, Hao Sun, Ye Lu, <strong>Beyond Agent Harnesses: Cross-Substrate Authority for Multi-Agent Systems</strong>, arXiv:2609.08472, first posted 2026-09-08 — <a href="https://arxiv.org/abs/2609.08472" target="_blank" rel="noreferrer">https://arxiv.org/abs/2609.08472</a></li><li>Full paper HTML — <a href="https://arxiv.org/html/2609.08472" target="_blank" rel="noreferrer">https://arxiv.org/html/2609.08472</a></li><li>Brian Jin, <strong>Fresh Context Is Not Enough: An Agent Action Needs a Valid Chain Back to Its Decision</strong>, DEV Community, 2026-09-11 — <a href="https://dev.to/kikashy/fresh-context-is-not-enough-an-agent-action-needs-a-valid-chain-back-to-its-decision-1afk" target="_blank" rel="noreferrer">https://dev.to/kikashy/fresh-context-is-not-enough-an-agent-action-needs-a-valid-chain-back-to-its-decision-1afk</a></li><li>Governed Deep Reading — <code>research/reading/A-20260916-01-cross-substrate-authority.md</code></li><li>Governed Research Analysis — <code>research/analysis/A-20260916-01-cross-substrate-authority.md</code></li></ol><p><strong>Evidence boundary:</strong> the arXiv paper is the primary evidence for this Academic object. All experimental counts are treated as source-reported and were not independently reproduced in this run. The four-substrate model and the “authority as a relation that survives to the mutation boundary” framing are Research Center synthesis. The secondary DEV Community article is contextual commentary, not an independent reproduction.</p>`,131))])}const v=s(p,[["render",c]]);export{g as __pageData,v as default};
